    nomes = []
    for jogador in jogadores:
        if jogador["pontos"] >= minimo:
            nomes.append(jogador["nome"])
    return nomes


def pontos_por_time(jogadores):
    totais = {}
    for jogador in jogadores:
        time = jogador["time"]
        totais[time] = totais.get(time, 0) + jogador["pontos"]
    return totais


