def adicionar(inv, item, qtd):
    inv[item] = inv.get(item, 0) + qtd


def remover(inv, item, qtd):
    if inv.get(item, 0) < qtd:
        return False
    inv[item] -= qtd
    if inv[item] == 0:
        del inv[item]
    return True


def relatorio(inv):
    if len(inv) == 0:
        return "Mochila vazia"
    linhas = []
    for item in sorted(inv):
        linhas.append(f"{item}: {inv[item]}")
    return "\n".join(linhas)


